        # =====================================================================
        self._veto_guards: Dict[str, Any] = {}
        if VETO_GUARD_AVAILABLE and _get_sf3().ENABLE_BITBEAST_RULES:
            try:
                for _vg_asset in ["BTC", "ETH", "SOL"]:
                    self._veto_guards[_vg_asset] = _VetoGuard(_vg_asset)
                logger.info(f"  [WIRE-VETO] BitBeastBehaviorGuard: ACTIVE ({len(self._veto_guards)} assets)")
            except Exception as e:
                logger.warning(f"  [WIRE-VETO] BitBeastBehaviorGuard init failed: {e}")

        # =====================================================================
        # [WARMUP] Structure Analyzers -feed historical 4H bars
        # Williams Fractal needs 5+ bars; BitBeast needs 11+ bars for swings.
        # Without warmup, ALL entries blocked for 20-44h after restart.
        # =====================================================================
        if (self.structure_analyzer or self._veto_guards) and self.config.mode in [RunMode.PAPER, RunMode.LIVE]:
            _warmup_exchange = None
            if self.kraken_rest and self.kraken_rest.is_initialized():
                _warmup_exchange = self.kraken_rest._exchange
            elif self._ccxt_exchange:
                _warmup_exchange = self._ccxt_exchange

            if _warmup_exchange:
                # [P133 2026-04-29] SOL on USDT pair (USD pair dead on Kraken).
                _WU_SYMBOLS = {"BTC": "BTC/USD", "ETH": "ETH/USD", "SOL": "SOL/USDT"}
                for _wa, _ws in _WU_SYMBOLS.items():
                    try:
                        _ohlcv = _warmup_exchange.fetch_ohlcv(_ws, "4h", limit=50)
                        if _ohlcv and len(_ohlcv) > 5:
                            _fed = 0
                            for _bar in _ohlcv[:-1]:  # exclude last (possibly incomplete) bar
                                _ts, _o, _h, _l, _c, _v = [float(x) for x in _bar]
                                if self.structure_analyzer:
                                    self.structure_analyzer.update(
                                        asset=_wa, high=_h, low=_l,
                                        close=_c, open_=_o, volume=_v,
                                    )
                                _vg = self._veto_guards.get(_wa)
                                if _vg:
                                    _vg.update(_h, _l, _c, _v)
                                _fed += 1
                            # Log fractal state after warmup
                            if self.structure_analyzer:
                                _levels = self.structure_analyzer.get_fractal_levels(_wa)
                                logger.info(
                                    f"  [WARMUP] {_wa}: {_fed} bars ->"
                                    f"{len(_levels['highs'])} fractal highs, "
                                    f"{len(_levels['lows'])} fractal lows"
                                )
                            else:
                                logger.info(f"  [WARMUP] {_wa}: {_fed} bars fed to BitBeast")
                    except Exception as e:
                        logger.warning(f"  [WARMUP] {_wa}: Structure warmup failed: {e}")
            else:
                logger.warning("  [WARMUP] No exchange available -structure analyzers cold-start")

