    def _get_learned_exec_runtime_snapshot(self) -> Dict[str, Any]:
        policy = getattr(self, "learned_exec_policy", None)
        snapshot = {
            "available": bool(policy),
            "configured_mode": "DISABLED",
            "effective_mode": "DISABLED",
            "weights_loaded": False,
            "heuristic_only": False,
            "network_usable": False,
            "validated_manifest_required": True,
            "validated_manifest_loaded": False,
            "validated_manifest_path": "",
            "validated_manifest_error": "",
            "validated_weights_sha256": "",
            "fused": False,
            "fuse_reason": "",
            "last_advice_source": "",
            "last_advice_reason": "",
        }
        if not policy:
            return snapshot

        configured_mode = str(
            getattr(getattr(policy, "config", None), "mode", "advisory") or "advisory"
        ).upper()
        snapshot["configured_mode"] = configured_mode

        status = {}
        get_status = getattr(policy, "get_status", None)
        if callable(get_status):
            try:
                status = dict(get_status() or {})
            except Exception:
                status = {}

        weights_loaded = bool(status.get("weights_loaded", getattr(policy, "weights_loaded", False)))
        heuristic_only = bool(status.get("heuristic_only", not weights_loaded))
        default_effective_mode = "SHADOW_HEURISTIC" if configured_mode == "SHADOW" else (
            "ADVISORY_HEURISTIC" if heuristic_only else "ADVISORY_LEARNED"
        )
        snapshot.update({
            "effective_mode": str(status.get("effective_mode", default_effective_mode) or default_effective_mode).upper(),
            "weights_loaded": weights_loaded,
            "heuristic_only": heuristic_only,
            "network_usable": bool(status.get("network_usable", weights_loaded and not heuristic_only)),
            "validated_manifest_required": bool(status.get("validated_manifest_required", True)),
            "validated_manifest_loaded": bool(status.get("validated_manifest_loaded", False)),
            "validated_manifest_path": str(status.get("validated_manifest_path", "") or ""),
            "validated_manifest_error": str(status.get("validated_manifest_error", "") or ""),
            "validated_weights_sha256": str(status.get("validated_weights_sha256", "") or ""),
            "fused": bool(status.get("fused", False)),
            "fuse_reason": str(status.get("fuse_reason", "") or ""),
            "last_advice_source": str(status.get("last_advice_source", "") or ""),
            "last_advice_reason": str(status.get("last_advice_reason", "") or ""),
        })
        return snapshot

