    def _generate_verification_data(self, asset: str) -> Dict[str, Any]:
        """[Phase 4C] Delegate to MarketDataPipeline."""
        return self._market_pipeline.generate_verification_data(asset)

    def _normalize_drl_paper_bootstrap_authority(self, requested: Any) -> str:
        """Paper bootstrap authority normalization.
        [UTIL-5] ACTIVE now allowed — auto-demotion safety (5 consec losses / 15% DD) still enforced.
        """
        normalized = str(requested or "").upper().strip()
        if normalized in ("ACTIVE", "EXIT_ONLY", "SHADOW", "DISABLED"):
            return normalized
        return ""

    def _get_drl_weight(self) -> float:
        """Dynamic DRL weight based on current authority level."""
        level = getattr(self, '_drl_authority_level', 'DISABLED')
        if level == "ACTIVE":
            return 0.40  # [FIX-DRL-WEIGHT] was 0.30. DRL sees 122 features
            # and correctly identifies recovery patterns that quant's EMA_200
            # misses in consolidation. 40% gives DRL enough voice to prevent
            # persistent wrong-direction trades from lagging EMA.
        elif level == "EXIT_ONLY":
            return 0.20  # was 0.15
        else:
            return 0.0  # SHADOW/DISABLED: invisible to trade gate

    def _sync_drl_authority(self, level: Optional[str] = None) -> None:
        """Propagate DRL authority to fusion/runtime surfaces from the main promotion gate."""
        resolved = str(level or getattr(self, "_drl_authority_level", "DISABLED") or "DISABLED").upper()
        _prev = getattr(self, '_drl_authority_level', 'DISABLED')
        self._drl_authority_level = resolved
        if _prev != resolved and self.audit_manager:
            try:
                from infra.persistence import AlertSeverity, AlertCategory
                self.audit_manager.log_event(
                    AlertSeverity.WARNING if resolved == "ACTIVE" else AlertSeverity.CRITICAL,
                    AlertCategory.SYSTEM,
                    f"DRL authority changed: {_prev} → {resolved}",
                    details={"previous": _prev, "new": resolved},
                )
            except Exception:
                pass
        try:
            if getattr(self, "engine", None) is not None and getattr(self.engine, "drl_gate", None) is not None:
                current = self.engine.drl_gate.get_authority().value
                if current != resolved:
                    self.engine.drl_gate.promote(resolved)
        except Exception as e:
            logger.debug(f"[DRL_GATE] engine sync failed: {e}")
        try:
            from signals.authority_fusion import set_drl_authority_level
            set_drl_authority_level(resolved)
        except ImportError:
            pass

    def _get_drl_authority_level(self) -> str:
        """Get DRL authority level from promotion gate."""
        if hasattr(self, '_promotion_gate') and self._promotion_gate:
            return self._promotion_gate.get_authority_level()
        return "DISABLED"

    def _get_drl_runtime_snapshot(self) -> Dict[str, Any]:
        """Return DRL runtime semantics for logs/dashboard."""
        def _level_name(value: Any) -> str:
            if value is None:
                return "DISABLED"
            if hasattr(value, "value"):
                return str(value.value)
            if hasattr(value, "name"):
                return str(value.name)
            return str(value)

        promotion_level = _level_name(self._get_drl_authority_level())
        gate_level = _level_name(getattr(self, "_drl_authority_level", promotion_level or "DISABLED"))
        models_ready = int(getattr(self, "_drl_models_ready", 0) or 0)
        inference_mode = str(getattr(self, "_drl_inference_mode", "DISABLED") or "DISABLED")
        if inference_mode == "DISABLED" and models_ready > 0:
            inference_mode = "SHADOW"
        execution_authority = "OFF" if gate_level in ("DISABLED", "SHADOW") else "ON"
        trade_impact = (
            "NONE" if gate_level in ("DISABLED", "SHADOW")
            else ("EXIT_ONLY" if gate_level == "EXIT_ONLY" else "FULL")
        )
        pnl_driver = bool(models_ready > 0 and gate_level in ("EXIT_ONLY", "ACTIVE"))
        ready_assets = sorted(
            asset for asset, ensemble in getattr(self, "_drl_ensembles", {}).items()
            if getattr(ensemble, "tqc_available", False)
        )
        return {
            "gate_level": gate_level,
            "promotion_level": promotion_level,
            "inference_mode": inference_mode,
            "execution_authority": execution_authority,
            "models_ready": models_ready,
            "ready_assets": ready_assets,
            "trade_impact": trade_impact,
            "pnl_driver": pnl_driver,
            "bootstrap_applied": bool(getattr(self, "_drl_bootstrap_applied", False)),
        }

    def _is_active_paper_position(self, position: Optional[Dict[str, Any]]) -> bool:
        """True when a paper position is economically non-flat."""
        if not position:
            return False
        try:
            exposure = abs(float(position.get("exposure", 0.0) or 0.0))
            direction = float(position.get("direction", 0.0) or 0.0)
            notional = abs(float(position.get("notional", 0.0) or 0.0))
        except Exception:
            return False
        return exposure > 1e-4 and abs(direction) > 0.1 and notional >= 1.0

    def _normalize_runtime_position_state(self, prune: bool = True) -> Dict[str, Dict[str, Any]]:
        """Drop ghost positions and rebuild entry-time metadata from active holdings."""
        active_positions: Dict[str, Dict[str, Any]] = {}
        removed_assets = []

        for asset, position in list(self._paper_positions.items()):
            if self._is_active_paper_position(position):
                active_positions[asset] = position
                continue
            removed_assets.append(asset)
            if prune:
                self._paper_positions.pop(asset, None)

        if removed_assets:
            logger.warning(
                f"[POSITION_NORMALIZE] Removed inactive paper positions: {', '.join(sorted(removed_assets))}"
            )

        rebuilt_entry_times: Dict[str, Dict[str, Any]] = {}
        for asset, position in active_positions.items():
            entry_ts = self._position_entry_times.get(asset, {}).get("entry_time")
            if entry_ts is None:
                raw_entry_time = position.get("entry_time")
                try:
                    entry_ts = datetime.fromisoformat(str(raw_entry_time).replace("Z", "+00:00"))
                    if entry_ts.tzinfo is None:
                        entry_ts = entry_ts.replace(tzinfo=timezone.utc)
                except Exception:
                    entry_ts = datetime.now(timezone.utc)
            rebuilt_entry_times[asset] = {
                "entry_time": entry_ts,
                "mode": position.get("mode_at_entry", self._position_entry_times.get(asset, {}).get("mode", "NORMAL")),
            }

        self._position_entry_times = rebuilt_entry_times
        return active_positions

    def _get_effective_position_state(
        self,
        asset: str,
        market_data: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Prefer restored paper positions over transient market_data exposure."""
        market_data = market_data or {}
        current_exposure = float(market_data.get("current_exposure", 0.0) or 0.0)
        direction = int(market_data.get("position_direction", 0) or 0)
        tranche = int(market_data.get("current_tranche", 0) or 0)

        if self.config.mode == RunMode.PAPER or (self.account_sync and self.account_sync.dry_run):
            paper_pos = self._paper_positions.get(asset)
            if paper_pos and self._is_active_paper_position(paper_pos):
                paper_direction = float(paper_pos.get("direction", 0.0) or 0.0)
                paper_exposure = abs(float(paper_pos.get("exposure", 0.0) or 0.0))
                if paper_direction != 0.0 and paper_exposure > 1e-6:
                    direction = 1 if paper_direction > 0 else -1
                    current_exposure = paper_exposure * direction
                    tranche = int(paper_pos.get("tranche", tranche) or tranche or 0)

        _has_position = abs(current_exposure) > 1e-6
        return {
            "current_exposure": current_exposure,
            "direction": direction,
            "tranche": tranche,
            "exposure": current_exposure,
            # [FIX-HAS-POS] has_position was always missing — soft_stop, gambler_exit,
            # exit_alpha, adaptive_stop all gate on this and were silently never firing.
            "has_position": _has_position,
        }

    def _normalize_existing_hold_intent(
        self,
        asset: str,
        intent: Any,
        position_state: Optional[Dict[str, Any]] = None,
    ) -> bool:
        """Preserve true no-op semantics for existing-position tranche HOLD."""
        position_state = position_state or {}
        if getattr(intent, "tranche_action", None) != "HOLD":
            return False

        current_exposure = float(position_state.get("current_exposure", 0.0) or 0.0)
        if abs(current_exposure) <= 1e-6:
            return False

        intent_direction = float(getattr(intent, "direction", 0.0) or 0.0)
        if intent_direction == 0.0 or (intent_direction * current_exposure) <= 0.0:
            return False

        current_abs_exposure = abs(current_exposure)
        target_abs_exposure = abs(float(getattr(intent, "target_exposure", 0.0) or 0.0))
        if abs(target_abs_exposure - current_abs_exposure) <= 1e-9:
            return False

        setattr(intent, "target_exposure", current_abs_exposure)
        setattr(intent, "is_addon", False)
        setattr(intent, "hold_existing_position_noop", True)
        logger.info(
            f"[HOLD_NOOP] {asset}: preserving existing exposure "
            f"{target_abs_exposure:.4f}->{current_abs_exposure:.4f} "
            f"(tranche=HOLD, dir={intent_direction:+.0f}, current={current_exposure:+.4f})"
        )
        return True

    def _get_effective_fee_bps(
        self,
        fee_context: Optional[Dict[str, Any]],
        *,
        is_maker: bool,
        default_bps: float,
    ) -> float:
        """Read effective fee bps from the shared fee context."""
        if not fee_context:
            return float(default_bps)
        key = "maker_fee_bps" if is_maker else "taker_fee_bps"
        try:
            return float(fee_context.get(key, default_bps) or default_bps)
        except Exception:
            return float(default_bps)

