    @staticmethod
    def _is_safety_exit_reason(exit_reason: str) -> bool:
        """Safety exits are exempt from anti-churn net-profit blocking."""
        if not exit_reason:
            return False
        tokens = {
            "stop_loss",
            "drawdown_halt",
            "p0_safety",
            "max_hold_timeout",
            "dead_man_switch",
            "leverage_guard",
            "FRICTION_EXCEEDS_EDGE",
            "T1_TRAILING_STOP",
            "T7_MAX_HOLD",
            "T10_SOFT_STOP",
            "T14_P0_FORCE",
            "FORCE_FLAT",
            "EMERGENCY",
            "CIRCUIT_BREAKER",
        }
        return any(token in exit_reason for token in tokens)

    def _maybe_block_micro_rebalance(
        self,
        *,
        asset: str,
        intent: Any,
        current_price: float,
        target_notional_usd: float,
        order_type: str,
        market_data: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        """Block voluntary partial exits/flips that cannot realize meaningful net PnL."""
        old_pos = self._paper_positions.get(asset)
        # [FIX-ANTI-CHURN-REDUCE] Organic reduces (is_reduce_intent=True) are risk
        # management actions — they lower exposure toward the current signal strength.
        # Anti-churn is for blocking micro-rebalances that crystallize losses for no
        # alpha reason. Reduces triggered by a weakening signal must always execute.
        if not old_pos or getattr(intent, "force_execution", False) or getattr(intent, "is_reduce_intent", False):
            return None

        current_notional = float(old_pos.get("notional", 0.0) or 0.0)
        current_dir = float(old_pos.get("direction", 0.0) or 0.0)
        if current_notional <= 0 or current_dir == 0 or current_price <= 0:
            return None

        target_dir = 0.0
        if getattr(intent, "direction", 0.0) > 0:
            target_dir = 1.0
        elif getattr(intent, "direction", 0.0) < 0:
            target_dir = -1.0

        is_flip = current_dir * target_dir < 0
        is_partial_exit = (
            target_dir != 0
            and current_dir * target_dir > 0
            and 0.0 < target_notional_usd < current_notional
        )
        if not (is_flip or is_partial_exit):
            return None

        exit_reason = str(getattr(intent, "veto_reason", "") or self._exit_trigger_tag.get(asset, ""))
        if self._is_safety_exit_reason(exit_reason):
            return None

        closed_notional_usd = current_notional if is_flip else max(0.0, current_notional - target_notional_usd)
        if closed_notional_usd <= 0:
            return None

        entry_price = float(old_pos.get("entry_price", 0.0) or 0.0)
        if entry_price <= 0:
            return None

        funding_total = float(old_pos.get("cumulative_funding_pnl", 0.0) or 0.0)
        close_fraction = min(1.0, max(0.0, closed_notional_usd / current_notional)) if current_notional > 0 else 0.0
        funding_pnl_usd = funding_total if is_flip else funding_total * close_fraction
        gross_pnl_usd = ((current_price - entry_price) / entry_price) * current_dir * closed_notional_usd
        fee_context = market_data.get("fee_context") if market_data else None
        fee_bps = self._get_effective_fee_bps(
            fee_context,
            is_maker=(order_type == "LIMIT"),
            default_bps=16.0 if order_type == "LIMIT" else 26.0,
        )
        exit_fee_usd = closed_notional_usd * fee_bps / 10000.0
        realized = self._build_realized_outcome(
            position=old_pos,
            gross_pnl_usd=gross_pnl_usd,
            closed_notional_usd=closed_notional_usd,
            exit_fee_usd=exit_fee_usd,
            funding_pnl_usd=funding_pnl_usd,
        )

        if (
            realized["net_pnl_usd"] >= self._MIN_REALIZED_NET_EXIT_USD
            and realized["net_pnl_bps"] >= self._MIN_REALIZED_NET_EXIT_BPS
        ):
            return None

        # Flips are directional changes, not profit-taking — exempt from anti-churn
        if is_flip:
            logger.info(
                f"[ANTI_CHURN_NET] {asset}: allowing FLIP "
                f"(net=${realized['net_pnl_usd']:+.2f}, exempt from anti-churn)"
            )
            return None

        action = "FLIP" if is_flip else "PARTIAL_EXIT"
        logger.info(
            f"[ANTI_CHURN_NET] {asset}: blocked {action} "
            f"gross=${realized['gross_pnl_usd']:+.2f} "
            f"net=${realized['net_pnl_usd']:+.2f} "
            f"net_bps={realized['net_pnl_bps']:+.1f} "
            f"(min=${self._MIN_REALIZED_NET_EXIT_USD:.2f}, "
            f"min_bps={self._MIN_REALIZED_NET_EXIT_BPS:.1f})"
        )
        return {
            "status": "ANTI_CHURN_NET_BLOCKED",
            "reason": (
                f"{action} net edge {realized['net_pnl_bps']:+.1f}bps / "
                f"${realized['net_pnl_usd']:+.2f} below minimum"
            ),
            "asset": asset,
            "action": action,
            "net_pnl_usd": realized["net_pnl_usd"],
            "net_pnl_bps": realized["net_pnl_bps"],
        }

    def _get_position_entry_fee_usd(self, position: Optional[Dict[str, Any]]) -> float:
        """Return the remaining entry-fee budget attached to an open paper position."""
        if not position:
            return 0.0
        raw_fee = position.get(
            "cumulative_entry_fees_usd",
            position.get("entry_fee_usd", 0.0),
        )
        try:
            return float(raw_fee or 0.0)
        except Exception:
            return 0.0

    def _build_realized_outcome(
        self,
        *,
        position: Optional[Dict[str, Any]],
        gross_pnl_usd: float,
        closed_notional_usd: float,
        exit_fee_usd: float = 0.0,
        funding_pnl_usd: float = 0.0,
    ) -> Dict[str, float]:
        """Normalize realized trade outcome into gross/net USD and bps."""
        gross_pnl_usd = float(gross_pnl_usd or 0.0)
        closed_notional_usd = float(closed_notional_usd or 0.0)
        exit_fee_usd = float(exit_fee_usd or 0.0)
        funding_pnl_usd = float(funding_pnl_usd or 0.0)

        position = position or {}
        position_notional_usd = float(position.get("notional", closed_notional_usd) or 0.0)
        total_entry_fee_usd = self._get_position_entry_fee_usd(position)

        if position_notional_usd > 0 and closed_notional_usd > 0:
            close_fraction = min(1.0, max(0.0, closed_notional_usd / position_notional_usd))
        else:
            close_fraction = 0.0

        entry_fee_allocated_usd = total_entry_fee_usd * close_fraction
        net_pnl_usd = gross_pnl_usd - entry_fee_allocated_usd - exit_fee_usd + funding_pnl_usd
        gross_pnl_bps = (
            gross_pnl_usd / closed_notional_usd * 10000.0
            if closed_notional_usd > 0
            else 0.0
        )
        net_pnl_bps = (
            net_pnl_usd / closed_notional_usd * 10000.0
            if closed_notional_usd > 0
            else 0.0
        )
        return {
            "gross_pnl_usd": gross_pnl_usd,
            "net_pnl_usd": net_pnl_usd,
            "gross_pnl_bps": gross_pnl_bps,
            "net_pnl_bps": net_pnl_bps,
            "entry_fee_allocated_usd": entry_fee_allocated_usd,
            "entry_fee_bps": (
                entry_fee_allocated_usd / closed_notional_usd * 10000.0
                if closed_notional_usd > 0
                else 0.0
            ),
            "exit_fee_usd": exit_fee_usd,
            "exit_fee_bps": (
                exit_fee_usd / closed_notional_usd * 10000.0
                if closed_notional_usd > 0
                else 0.0
            ),
            "funding_pnl_usd": funding_pnl_usd,
            "close_fraction": close_fraction,
            "remaining_entry_fee_usd": max(total_entry_fee_usd - entry_fee_allocated_usd, 0.0),
        }

    @staticmethod
    def _clip_float(value: Any, *, default: float = 0.0, lower: Optional[float] = None, upper: Optional[float] = None) -> float:
        try:
            result = float(value)
        except Exception:
            result = float(default)
        if not math.isfinite(result):
            result = float(default)
        if lower is not None:
            result = max(lower, result)
        if upper is not None:
            result = min(upper, result)
        return result

    @staticmethod
    def _rolling_zscore(current_value: float, history: deque, *, min_points: int = 10, clip: float = 10.0) -> float:
        values = [float(v) for v in history if isinstance(v, (int, float)) and math.isfinite(float(v))]
        if len(values) < min_points:
            return 0.0
        mean = sum(values) / len(values)
        variance = sum((v - mean) ** 2 for v in values) / max(len(values), 1)
        std = variance ** 0.5
        if std <= 1e-10:
            return 0.0
        score = (float(current_value) - mean) / std
        return max(-clip, min(clip, score))

    @staticmethod
    def _pct_change_from_history(current_value: float, history: deque, *, periods: int = 30, clip: float = 5.0) -> float:
        values = [float(v) for v in history if isinstance(v, (int, float)) and math.isfinite(float(v))]
        if len(values) <= periods:
            return 0.0
        previous = values[-(periods + 1)]
        if abs(previous) <= 1e-10:
            return 0.0
        change = (float(current_value) - previous) / abs(previous)
        return max(-clip, min(clip, change))

    def _get_runtime_feature_bar_ts(self, asset: str, market_data: Optional[Dict[str, Any]]) -> Optional[str]:
        if market_data:
            ohlcv_raw = market_data.get("ohlcv_raw")
            if ohlcv_raw:
                try:
                    return str(ohlcv_raw[-1][0])
                except Exception:
                    pass
        ta_cache = getattr(self, "_ta_cache", {}).get(asset)
        if ta_cache and ta_cache.get("last_ts") is not None:
            return str(ta_cache["last_ts"])
        return None

    def _derive_runtime_external_features(self, asset: str, market_data: Optional[Dict[str, Any]]) -> None:
        """Approximate training external features from live feed + trade activity."""
        if not market_data:
            return

        asset_key = asset.replace("/USD", "").upper()
        histories = self._runtime_external_history.get(asset_key)
        if histories is None:
            return

        funding_rate = self._clip_float(market_data.get("funding_rate", 0.0))
        open_interest = self._clip_float(market_data.get("open_interest", 0.0), lower=0.0)
        liq_imbalance = self._clip_float(
            market_data.get("liquidation_imbalance", market_data.get("liq_imbalance", 0.0)),
            lower=-1.0,
            upper=1.0,
        )

        taker_volume_usd = self._clip_float(market_data.get("recent_taker_volume_usd", 0.0), lower=0.0)
        trade_count = self._clip_float(market_data.get("recent_trade_count", 0.0), lower=0.0)
        trade_source = str(market_data.get("trade_metrics_source", "") or "")

        if taker_volume_usd <= 0.0:
            ta_cache = getattr(self, "_ta_cache", {}).get(asset_key) or getattr(self, "_ta_cache", {}).get(asset)
            ohlcv_df = None
            if ta_cache:
                ohlcv_df = ta_cache.get("drl_df") or ta_cache.get("df")
            if ohlcv_df is not None and len(ohlcv_df) > 0:
                try:
                    last_close = self._clip_float(ohlcv_df["close"].iloc[-1], lower=0.0)
                    last_volume = self._clip_float(ohlcv_df["volume"].iloc[-1], lower=0.0)
                    taker_volume_usd = max(taker_volume_usd, last_close * last_volume)
                    if trade_source == "":
                        trade_source = "ohlcv_proxy"
                except Exception:
                    pass

        if trade_count <= 0.0 and taker_volume_usd > 0.0:
            avg_ticket_usd = max(self._clip_float(market_data.get("current_price", 0.0), lower=0.0) * 0.02, 50.0)
            trade_count = float(max(1, min(5000, int(taker_volume_usd / avg_ticket_usd))))
            if trade_source == "":
                trade_source = "ohlcv_proxy"

        bar_ts = self._get_runtime_feature_bar_ts(asset_key, market_data)
        if bar_ts is not None and self._runtime_external_last_bar_ts.get(asset_key) != bar_ts:
            if "funding_rate" in market_data or market_data.get("funding_rate_source"):
                histories["funding_rate"].append(funding_rate)
            if "open_interest" in market_data and open_interest > 0.0:
                histories["open_interest"].append(open_interest)
            if taker_volume_usd > 0.0:
                histories["taker_volume_usd"].append(taker_volume_usd)
            if trade_count > 0.0:
                histories["trade_count"].append(trade_count)
            self._runtime_external_last_bar_ts[asset_key] = bar_ts

        market_data["funding_rate_zscore"] = self._rolling_zscore(funding_rate, histories["funding_rate"])
        market_data["oi_change_5d"] = self._pct_change_from_history(open_interest, histories["open_interest"], periods=30)
        market_data["liq_imbalance"] = liq_imbalance
        market_data["taker_ratio_zscore"] = self._rolling_zscore(taker_volume_usd, histories["taker_volume_usd"])
        market_data["tradecount_zscore"] = self._rolling_zscore(trade_count, histories["trade_count"])
        market_data["taker_vol_momentum"] = self._pct_change_from_history(
            taker_volume_usd,
            histories["taker_volume_usd"],
            periods=30,
        )

        has_crowd_feed = any(
            key in market_data for key in ("funding_rate", "open_interest", "liquidation_imbalance")
        )
        has_live_trade_metrics = trade_source == "kraken_trades"
        market_data["has_external_data"] = 1.0 if (has_crowd_feed or has_live_trade_metrics) else 0.0
        market_data["trade_metrics_source"] = trade_source or "none"

    def _all_trade_gates(self):
        """Return all unique TradeGate instances (main + p0_safety)."""
        gates = []
        if self.trade_gate:
            gates.append(self.trade_gate)
        if hasattr(self, 'p0_integrator') and self.p0_integrator and hasattr(self.p0_integrator, 'trade_gate') and self.p0_integrator.trade_gate and self.p0_integrator.trade_gate is not self.trade_gate:
            gates.append(self.p0_integrator.trade_gate)
        return gates

    # =========================================================================
    # TRANCHE STATE PERSISTENCE (across restarts)
    # =========================================================================

    _TRANCHE_STATE_FILE = DATA_DIR / "tranche_state.json"  # [FIX-37]

    def _sync_tranche_scheduler_with_paper_positions(self) -> None:
        """Remove stale scheduler positions and align active ones to paper truth."""
        try:
            scheduler = self.engine.guarantees.tranche_scheduler
        except Exception:
            return

        active_positions = {
            asset: pos
            for asset, pos in self._paper_positions.items()
            if self._is_active_paper_position(pos)
        }
        removed_assets = set()

        for asset in list(getattr(scheduler, "positions", {}).keys()):
            if asset not in active_positions:
                scheduler.positions.pop(asset, None)
                removed_assets.add(asset)

        try:
            from defense.constitution import TrancheLevel
        except Exception:
            TrancheLevel = None

        _positions_need_save = False
        for asset, live_pos in active_positions.items():
            sched_pos = scheduler.get_position(asset)
            live_direction = float(live_pos.get("direction", 0.0) or 0.0)
            live_exposure = abs(float(live_pos.get("exposure", 0.0) or 0.0))
            if live_direction == 0.0 or live_exposure <= 1e-6:
                scheduler.positions.pop(asset, None)
                removed_assets.add(asset)
                continue

            tranche_level = int(live_pos.get("tranche", 0) or 0)
            existing_level = int(getattr(getattr(sched_pos, "level", None), "value", 0) or 0)
            if tranche_level < 1 or tranche_level > 4:
                tranche_level = existing_level if 1 <= existing_level <= 4 else 1
                # Write corrected tranche back to paper_positions so DRL observations
                # and deadlock resolver see the correct level (not 0 from stale data).
                _stored_tranche = int(live_pos.get("tranche", 0) or 0)
                if _stored_tranche != tranche_level:
                    live_pos["tranche"] = tranche_level
                    self._paper_positions[asset] = live_pos
                    _positions_need_save = True
                    logger.info(
                        f"[TRANCHE_SYNC] {asset}: corrected paper tranche "
                        f"{_stored_tranche}->{tranche_level} (from scheduler level)"
                    )

            if TrancheLevel is not None:
                try:
                    sched_pos.level = TrancheLevel(tranche_level)
                except Exception:
                    pass
            sched_pos.direction = "long" if live_direction > 0 else "short"
            sched_pos.target_exposure = live_exposure

            # [P112 2026-04-27] Wire tranche_manager.update_executed (was
            # never called per audit gap 9b). The previous direct mutation
            # of `sched_pos.current_exposure = live_exposure` overwrote
            # the field but skipped the weighted-avg avg_price math
            # inside update_executed (lines 710-723 of tranche_manager.py).
            # Without that, T3 PnL escalation thresholds use the entry_price
            # from the FIRST fill, ignoring price drift across T1→T2→T3
            # add-on fills. Now: call update_executed so avg_price tracks
            # actual fill economics. Wrapped in try so existing sync flow
            # is robust if tranche_manager API ever changes.
            entry_price = float(live_pos.get("entry_price", 0.0) or 0.0)
            try:
                if hasattr(scheduler, "update_executed") and entry_price > 0:
                    scheduler.update_executed(asset, live_exposure, entry_price)
                else:
                    sched_pos.current_exposure = live_exposure
                    if entry_price > 0:
                        sched_pos.entry_price = entry_price
            except Exception as _ue_err:
                logger.warning(
                    f"[TRANCHE_SYNC] {asset}: update_executed failed "
                    f"({type(_ue_err).__name__}: {_ue_err}); falling back "
                    f"to direct mutation"
                )
                sched_pos.current_exposure = live_exposure
                if entry_price > 0:
                    sched_pos.entry_price = entry_price

            entry_meta = self._position_entry_times.get(asset, {})
            entry_time = entry_meta.get("entry_time")
            if entry_time is None:
                raw_entry_time = live_pos.get("entry_time")
                if raw_entry_time:
                    try:
                        entry_time = datetime.fromisoformat(str(raw_entry_time).replace("Z", "+00:00"))
                        if entry_time.tzinfo is None:
                            entry_time = entry_time.replace(tzinfo=timezone.utc)
                    except Exception:
                        entry_time = None
            if entry_time is not None:
                sched_pos.entered_at = entry_time

        if removed_assets:
            logger.warning(
                f"[TRANCHE_PERSIST] Removed stale tranche state: {', '.join(sorted(removed_assets))}"
            )
        if _positions_need_save and self.config.mode != RunMode.VERIFY:
            try:
                self._save_paper_positions(force=True)
            except Exception as _e:
                logger.debug(f"[TRANCHE_SYNC] paper_positions save failed: {_e}")

    def _persist_governor_state(self) -> None:
        """[F7-PERSIST 2026-04-15] Save governor states (confidence, failure_memory,
        cascade, thesis_budget, opportunity_budget) for restart recovery.

        Without this, every restart resets confidence learning, failure memory
        counters, cascade exhaustion guards, and thesis budget tracking — the
        system goes amnesiac on every container restart.
        """
        try:
            from core.state_persistence import save_state as _ps
        except Exception:
            return

        # Confidence scorer (uses its own save_state method)
        try:
            if self._confidence_scorer is not None and hasattr(self._confidence_scorer, 'save_state'):
                self._confidence_scorer.save_state()
        except Exception as _e:
            # P83: was logger.debug — silent governor amnesia on restart.
            # Sibling FIX-27 code at lines 14314-14342 logs same failures
            # at WARNING. Aligned to match operator visibility.
            logger.warning(f"[F7] confidence_scorer save: {type(_e).__name__}: {_e}")

        # Failure memory (has to_dict/from_dict but no I/O)
        try:
            if self._failure_memory is not None and hasattr(self._failure_memory, 'to_dict'):
                _ps("data/failure_memory_state.json", self._failure_memory.to_dict())
        except Exception as _e:
            # P83: same as above — promote DEBUG → WARNING
            logger.warning(f"[F7] failure_memory save: {type(_e).__name__}: {_e}")

        # Cascade exhaustion governor (singleton, has to_dict)
        try:
            from risk.cascade_exhaustion_governor import get_cascade_exhaustion_governor
            _gov = get_cascade_exhaustion_governor()
            if _gov is not None and hasattr(_gov, 'to_dict'):
                _ps("data/cascade_governor_state.json", _gov.to_dict())
        except Exception as _e:
            # P83: same as above — promote DEBUG → WARNING
            logger.warning(f"[F7] cascade_gov save: {type(_e).__name__}: {_e}")

        # Thesis budget governor
        try:
            if self.thesis_budget_governor is not None and hasattr(self.thesis_budget_governor, 'to_dict'):
                _ps("data/thesis_budget_state.json", self.thesis_budget_governor.to_dict())
        except Exception as _e:
            # P83: same as above — promote DEBUG → WARNING
            logger.warning(f"[F7] thesis_budget save: {type(_e).__name__}: {_e}")

    def _restore_governor_state(self) -> None:
        """[F7-PERSIST 2026-04-15] Restore governor states at startup."""
        try:
            from core.state_persistence import load_state as _ls
        except Exception:
            return

        try:
            if self._failure_memory is not None and hasattr(self._failure_memory, 'from_dict'):
                if (data := _ls("data/failure_memory_state.json")):
                    self._failure_memory.from_dict(data)
                    logger.info("[F7] failure_memory state restored")
        except Exception as _e:
            logger.debug(f"[F7] failure_memory restore: {_e}")

        try:
            from risk.cascade_exhaustion_governor import get_cascade_exhaustion_governor
            _gov = get_cascade_exhaustion_governor()
            if _gov is not None and hasattr(_gov, 'from_dict'):
                if (data := _ls("data/cascade_governor_state.json")):
                    _gov.from_dict(data)
                    logger.info("[F7] cascade_governor state restored")
        except Exception as _e:
            logger.debug(f"[F7] cascade_gov restore: {_e}")

        try:
            if self.thesis_budget_governor is not None and hasattr(self.thesis_budget_governor.__class__, 'from_dict'):
                # Note: thesis_budget_governor.from_dict is a classmethod that returns NEW instance
                # We just ensure data file is loadable; full restore requires re-init pattern
                if (data := _ls("data/thesis_budget_state.json")):
                    logger.info(f"[F7] thesis_budget state file present (governor uses classmethod restore)")
        except Exception as _e:
            logger.debug(f"[F7] thesis_budget restore: {_e}")

    def _persist_tranche_state(self) -> None:
        """Save all tranche positions to disk for restart recovery."""
        try:
            scheduler = self.engine.guarantees.tranche_scheduler
            state = {}
            active_positions = {
                asset: pos
                for asset, pos in self._paper_positions.items()
                if self._is_active_paper_position(pos)
            }
            for asset, pos in scheduler.positions.items():
                live_pos = active_positions.get(asset)
                if live_pos is None or getattr(pos.level, "value", 0) <= 0:
                    continue
                live_direction = float(live_pos.get("direction", 0.0) or 0.0)
                live_exposure = abs(float(live_pos.get("exposure", 0.0) or 0.0))
                if live_direction == 0.0 or live_exposure <= 1e-6:
                    continue
                entry_price = float(live_pos.get("entry_price", pos.entry_price) or pos.entry_price or 0.0)
                state[asset] = {
                    "level": int(live_pos.get("tranche", getattr(pos.level, "value", 0)) or getattr(pos.level, "value", 0)),
                    "direction": "long" if live_direction > 0 else "short",
                    "target_exposure": live_exposure,
                    "current_exposure": live_exposure,
                    "entry_price": entry_price,
                    "unrealized_pnl_bps": pos.unrealized_pnl_bps,
                    "entered_at": pos.entered_at.isoformat() if pos.entered_at else None,
                    "last_escalation": pos.last_escalation.isoformat() if pos.last_escalation else None,
                }
            self._TRANCHE_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
            tmp = self._TRANCHE_STATE_FILE.with_suffix(".tmp")
            # [FIX-40] fsync
            with open(tmp, 'w') as _f:
                _f.write(json.dumps(state, indent=2))
                _f.flush()
                os.fsync(_f.fileno())
            tmp.replace(self._TRANCHE_STATE_FILE)
        except Exception as e:
            logger.warning(f"[TRANCHE_PERSIST] Save failed: {e}")

    def _build_drl_env_state(self, asset: str) -> list:
        """Build [position_ratio, position_direction, pnl_ratio, drawdown] for DRL obs."""
        pos = self._paper_positions.get(asset, {})
        exposure = pos.get("exposure", 0.0)
        direction = pos.get("direction", 0.0)
        # position_ratio: exposure is already 0-1 fraction
        pos_ratio = float(exposure)
        pos_dir = float(direction)
        # pnl_ratio: total PnL / initial capital
        _total_pnl = getattr(self, '_total_leveraged_pnl', 0.0)
        pnl_ratio = _total_pnl / self.config.initial_capital if self.config.initial_capital > 0 else 0.0
        # drawdown: from existing tracker
        dd = getattr(self, '_current_drawdown_pct', 0.0)
        return [pos_ratio, pos_dir, pnl_ratio, dd]

    def _load_tranche_state(self) -> None:
        """Restore tranche positions from disk after restart."""
        if not self._TRANCHE_STATE_FILE.exists():
            return
        try:
            state = json.loads(self._TRANCHE_STATE_FILE.read_text())
            scheduler = self.engine.guarantees.tranche_scheduler
            from defense.constitution import TrancheLevel
            restored = 0
            for asset, data in state.items():
                pos = scheduler.get_position(asset)
                saved_level = data.get("level", 0)
                if saved_level == 0:
                    continue  # No position to restore
                pos.level = TrancheLevel(saved_level)
                pos.direction = data.get("direction", "none")
                pos.target_exposure = data.get("target_exposure", 0.0)
                pos.current_exposure = data.get("current_exposure", 0.0)
                pos.entry_price = data.get("entry_price", 0.0)
                pos.unrealized_pnl_bps = data.get("unrealized_pnl_bps", 0.0)
                if data.get("entered_at"):
                    pos.entered_at = datetime.fromisoformat(data["entered_at"])
                if data.get("last_escalation"):
                    pos.last_escalation = datetime.fromisoformat(data["last_escalation"])
                restored += 1
                logger.info(
                    f"[TRANCHE_PERSIST] Restored {asset}: "
                    f"level={pos.level.name}, dir={pos.direction}, "
                    f"exposure={pos.current_exposure:.4f}, entry=${pos.entry_price:.2f}"
                )
            if restored:
                logger.info(f"[TRANCHE_PERSIST] Restored {restored} tranche positions from disk")
        except Exception as e:
            logger.warning(f"[TRANCHE_PERSIST] Load failed (starting fresh): {e}")

